from __future__ import annotations

from typing import Self
import math
import cmath

PI = 3.141592653589793
TWOPI = 2 * PI
HALFPI = PI / 2
ZEROTOL = 1e-12


def _reduce_fraction(nom: int, den: int | None):
    if den is None:
        return (nom, None)
    if den < 0:
        den = -den
        nom = -nom
    gcd = math.gcd(nom, den)
    if den == gcd:
        return nom // gcd, None
    return nom // gcd, den // gcd


class Coeff:
    """The coefficient base class.

    This class is not supposed to be instantiated
    """

    def mul_queue(self, *vals, **_kwargs) -> Self:
        """append the value to the scalar queue to be multiplied"""
        raise NotImplementedError(
            "operation 'mul_queue' must be implemented by the subclass"
        )

    def div_queue(self, *vals, **_kwargs) -> Self:
        """append the value to the scalar queue to be divided"""
        raise NotImplementedError(
            "operation 'div_queue' must be implemented by the subclass"
        )

    def jshift(self, num: int, /) -> Self:
        """apply num multiplications with 1j"""
        raise NotImplementedError(
            "operation 'imshift' must be implemented by the subclass"
        )


def autoconvert(func):
    """
    A wrapper to handle a proper copy mechanism if the first argument
    of the init routine is a Scalar object itself.
    If a 'first' arg is given, it is unpacked. If it is None, go on as usual.
    In any case, the actual wrapped __init__ will not get a 'first' arg at any
    point.
    """

    def wrapper(self, first=None, /, **kwargs):
        if first is None:
            return func(self, **kwargs)  # ignore

        # ok, so first is not None
        if isinstance(first, Scalar):
            return func(self, **first.unpack())

        # ok, so not a scalar
        if isinstance(first, int):
            return func(self, rnom=first, **kwargs)
        if isinstance(first, float):
            return func(self, real=first, **kwargs)
        num = complex(first)
        return func(self, real=num.real, imag=num.imag, **kwargs)

    return wrapper


class Scalar(Coeff):
    r"""
    A general scalar type as subtype of a coefficient.

    This class represents a universal scalar without any restrictions,
    including symbolic support.
    Internally it expresses any complex expression as

                                j phas  / rnom   inom   \     jpow
    z = (real + imag j) x magn e      x | ---- + ---- j | x  j
                                        \ rden   iden   /

    where ints are always strictly accumulated in fractions while
    real/imag or magn/phas can both accumulate irrational contributions.
    Ideally, global signs and multiples of pi/2 can be accumulated in jpow
    to speed up phase swaps of multiples of 90°.
    """

    @autoconvert
    def __init__(
        self,
        real: float = 0.0,
        imag: float = 0.0,
        rnom: int = 1,
        rden: int | None = None,
        inom: int = 0,
        iden: int | None = None,
        magn: float = 1.0,
        phas: float = 0.0,
        jpow: int = 0,
        nega: bool = False,
        symb: list[tuple[str, int | float]] | None = None,
        polar=False,
        simplify=True,
    ):
        self._nega = nega
        self._real = real
        self._imag = imag
        self._rnom = rnom
        self._rden = rden
        self._inom = inom
        self._iden = iden
        self._magn = magn
        self._phas = phas
        self._jpow = jpow
        self._ppol = polar  # polar priority

        # contract symbols
        symb_dict: dict[str, int | float] = {}
        if symb:
            for symbol, exponent in symb:
                if symbol not in symb_dict:
                    symb_dict[symbol] = 0
                symb_dict[symbol] += exponent
        self._symb = symb_dict
        if simplify:
            self.simplify()

    def to_decimal(self) -> Self:
        """rearrange all fraction content to decimals"""
        # TODO
        raise NotImplementedError("conversion to decimal not yet implemented")
        # return self

    def simplify(
        self, floats=True, polar=True, symbol=True, fracs=True
    ) -> Self:
        """reduces fractions and handles phase"""
        if floats:
            self._floats_simplify()
        if polar:
            self._polar_simplify()
        if fracs:
            self._fracs_simplify()
        if symbol:
            self._symbol_simplify()
        self._rearrange()
        return self

    def _floats_simplify(self) -> Self:
        """simplify the floats part"""
        if self._real < 0:
            self._real = -self._real
            self._imag = -self._imag
            self._nega = not self._nega
        return self

    def _polar_simplify(self) -> Self:
        """simplify the polar part"""
        if self._magn < 0:
            self._magn = -self._magn
            self._nega = not self._nega
        return self

    def _fracs_simplify(self) -> Self:
        """reduce fractions"""
        if self._rden is not None:
            self._rnom, self._rden = _reduce_fraction(self._rnom, self._rden)
        if self._iden is not None:
            self._inom, self._iden = _reduce_fraction(self._inom, self._iden)
        if self._rnom < 0:
            self._rnom = -self._rnom
            self._inom = -self._inom
            self._nega = not self._nega
        return self

    def _symbol_simplify(self) -> Self:
        """simplify the symbol part"""
        return self

    def _rearrange(self) -> Self:
        """rearrange the decimal contributions between polar and non polar"""
        # make leading real part positive
        if self.polar:
            # polar case catches global js and minus-sign
            if self._nega:
                self._jpow += 2
                self._nega = False
            # put j power into the exponent
            self._phas += (self._jpow % 4) * HALFPI
            self._jpow = 0
        else:
            self._jpow %= 4
            # TODO:
            # dissolve j to variables

        self._phas %= TWOPI  # mod 2pi
        return self

    def conjugate(self) -> Scalar:
        """return a new scalar object that is the conjugate"""
        # TODO
        raise NotImplementedError("operation not yet implemented")

    def mul_queue(self, *vals, simplify=True, **_kwargs) -> Self:
        """append the value to the scalar queue to be multiplied"""
        for val in vals:
            if isinstance(val, int):
                if self._rden is not None:
                    self._rnom *= val
                if self._iden is not None:
                    self._inom *= val
            elif isinstance(val, float):
                if self.polar:
                    self._magn *= val
                else:
                    self._real *= val
                    self._imag *= val
            elif isinstance(val, complex):
                if self.polar:
                    self._magn *= abs(val)
                    self._phas += cmath.phase(val)
                else:
                    new_real = val.real * self._real - val.imag * self._imag
                    new_imag = val.imag * self._real + val.real * self._imag
                    self._real = new_real
                    self._imag = new_imag
            else:
                raise ValueError(f"Unsupported type: {type(val)}")
        if simplify:
            self.simplify()
        return self

    def div_queue(self, *vals, simplify=True, **_kwargs) -> Self:
        """append the value to the scalar queue to be divided"""
        for val in vals:
            if isinstance(val, int):
                if self._rden is None:
                    self._rden = 1
                self._rden *= val
                if self._iden is None:
                    self._iden = 1
                self._iden *= val
            elif isinstance(val, float):
                if self.polar:
                    self._magn /= val
                else:
                    self._real /= val
                    self._imag /= val
            elif isinstance(val, complex):
                if self.polar:
                    self._magn /= abs(val)
                    self._phas -= cmath.phase(val)
                else:
                    new_complex = (self._real + 1j * self._imag) / val
                    self._real = new_complex.real
                    self._imag = new_complex.imag
            else:
                raise ValueError(f"Unsupported type: {type(val)}")
        if simplify:
            self.simplify()
        return self

    def jshift(self, num: int, /, *, simplify=True) -> Self:
        """apply num multiplications with 1j"""
        if not isinstance(num, int):
            raise ValueError("jshift requires an integer argument")
        self._jpow += num
        if simplify:
            self.simplify()
        return self

    def flip_sign(self, num: int = 1) -> Self:
        """applies the negation num times, num defaults to 1"""
        if num & 1:
            self._nega = not self._nega
        return self

    @classmethod
    def identity(cls):
        """create a perfect one or its equivalent"""
        return cls(1)

    @classmethod
    def zero(cls):
        """create a perfect zero or its equivalent"""
        return cls(0)

    @property
    def polar(self):
        """get the polar priority of the variable"""
        return self._ppol

    @polar.setter
    def polar(self, value):
        """set if priority is polar"""
        if not isinstance(value, bool):
            raise ValueError("polar priority must be a boolean")
        self._ppol = value
        self.simplify()

    @property
    def is_numerical(self):
        """check if the scalar is purely numerical, i.e. no symbols left"""
        if self._symb:
            return False
        return True

    @property
    def is_real(self):
        """check if the number is real. Symbols are assumed to be real"""
        return abs(self.imag) < ZEROTOL

    def unpack(self):
        """unpack the generating values for the scalar"""
        return {
            "nega": self._nega,
            "real": self._real,
            "imag": self._imag,
            "rnom": self._rnom,
            "rden": self._rden,
            "inom": self._inom,
            "iden": self._iden,
            "magn": self._magn,
            "phas": self._phas,
            "jpow": self._jpow,
            "symb": self._symb,
        }

    # binary aux
    # ----------

    @classmethod
    def _no_simplify_mul(cls, first, second) -> Scalar:
        return cls(first._real * second._real)
        # TODO

    @classmethod
    def _no_simplify_div(cls, first, second) -> Scalar:
        return cls(first._real / second._real)
        # TODO

    @classmethod
    def _no_simplify_add(cls, first, second) -> Scalar:
        return cls(first._real + second._real)
        # TODO

    @classmethod
    def _no_simplify_sub(cls, first, second) -> Scalar:
        return cls(first._real - second._real)
        # TODO

    @classmethod
    def _no_simplify_pow(cls, first, second) -> dict:
        return cls(first._real**second._real)
        # TODO

    # binary special
    # --------------

    def __mul__(self, other):
        if not isinstance(other, Scalar):
            other = self.__class__(other)

        print(self.unpack())
        print(other.unpack())
        return self._no_simplify_mul(self, other).simplify()

    def __div__(self, other):
        if not isinstance(other, Scalar):
            other = self.__class__(other)
        return self._no_simplify_div(self, other).simplify()

    def __truediv__(self, other):
        if not isinstance(other, Scalar):
            other = self.__class__(other)
        return self._no_simplify_div(self, other).simplify()

    def __add__(self, other):
        if not isinstance(other, Scalar):
            other = self.__class__(other)
        return self._no_simplify_add(self, other).simplify()

    def __sub__(self, other):
        if not isinstance(other, Scalar):
            other = self.__class__(other)
        return self._no_simplify_sub(self, other).simplify()

    def __pow__(self, exponent):
        return self._no_simplify_pow(self, exponent).simplify()

    # right side binary special
    # -------------------------

    # the __rx__ routines are called if the left operator has not routine x
    def __rmul__(self, other):
        return self._no_simplify_mul(self.__class__(other), self).simplify()

    def __rdiv__(self, other):
        return self._no_simplify_div(self.__class__(other), self).simplify()

    def __rtruediv__(self, other):
        return self._no_simplify_div(self.__class__(other), self).simplify()

    def __radd__(self, other):
        return self._no_simplify_add(self.__class__(other), self).simplify()

    def __rsub__(self, other):
        return self._no_simplify_sub(self.__class__(other), self).simplify()

    def __rpow__(self, exponent):
        return self._no_simplify_pow(self, exponent).simplify()

    # non-binary special routines
    # ---------------------------

    def __neg__(self) -> Scalar:
        return self.__class__(self).flip_sign().simplify()

    def __abs__(self) -> float:
        return math.sqrt(self.real**2 + self.imag**2)

    # type casts
    # ----------

    def __int__(self) -> int:
        if not self.is_real:
            raise ValueError("Scalar is not a real number")
        return int(self.real)

    def __float__(self) -> float:
        if not self.is_real:
            raise ValueError("Scalar is not a real number")
        return float(self.real)

    def __complex__(self) -> complex:
        return self.real + 1j * self.imag

