class ScalarPython(Scalar):
    """Default scalar, designed to wrap python scalars"""

    def __init__(self, value=0, **kwargs):
        """only take one value"""
        super().__init__(value, polar=False, **kwargs)


class ScalarCComplex(Scalar):
    """
    ScalarCComplex represents a complex value.

    In contrast to the python scalar wrapper, it distinguishes real and imag
    part explicitely as components.
    """

    def __init__(self, real=0.0, imag=0.0, **kwargs):
        super().__init__(real, imag, **kwargs)

    @property
    def real(self):
        """acccess the real part"""
        return self._vals[0]

    @real.setter
    def real(self, value):
        """set the value of alias 'real'"""
        self._vals = (value, self._vals[1])

    @property
    def imag(self):
        """acccess the real part"""
        return self._vals[1]

    @imag.setter
    def imag(self, value):
        """set the value of alias 'imag'"""
        self._vals = (self._vals[0], value)


class ScalarPComplex(Scalar):
    """
    ScalarPComplex represents a complex value in polar form via a magnitude
    and a phase.
    """

    def __init__(self, magn=0.0, phase=0.0, **kwargs):
        super().__init__(magn, phase, **kwargs)

    @property
    def magnitude(self):
        """acccess the magnitude part"""
        return self._vals[0]

    @magnitude.setter
    def magnitude(self, value):
        """set the value of alias 'magnitude'"""
        self._vals = (value, self._vals[1])

    @property
    def phase(self):
        """acccess the phase part"""
        return self._vals[1]

    @phase.setter
    def phase(self, value):
        """set the value of alias 'phase'"""
        self._vals = (self._vals[0], value)

    def __abs__(self):
        return self.magnitude


class ScalarRFraction(Scalar):
    """
    A fraction of real (!) ints.

    dnom is always >= 1.
    """

    def __init__(
        self,
        nom: int = 1,
        den: int = 1,
        **kwargs,
    ):
        super().__init__(nom, den, **kwargs)


class ScalarCFraction(Scalar):
    """
    A complex fraction of ints.

    Real and imag part can have their own denominator to have proper nominator
    values when real/imag >> 1 or imag/real >> 1.
    """

    def __init__(
        self,
        rnom: int = 1,
        rden: int = 1,
        inom: int = 0,
        iden: int = 1,
        **kwargs,
    ):
        super().__init__(rnom, rden, inom, iden, **kwargs)


class ScalarSymbolic(Scalar):
    """A symbolic variable, represented by a letter and its power"""

    def __init__(self, *scals, **powers):
        # assume the scals are of some compatible input type.
        super().__init__()
        self._powers = {}
        for varname, power in powers.items():
            self._powers[varname] = power


