class Summand:
    """
    Summand class
    """

    _DEFAULT_COEFF = Scalar  # default class to create scalars from

    def __init__(self, bases, elems, scalar=None):
        self._elems = elems
        self._bases = bases
        if scalar is None:
            scalar = self._DEFAULT_COEFF.identity()
        elif not isinstance(scalar, Coeff):
            scalar = self._DEFAULT_COEFF(scalar)
        self.scalar = scalar


class Operator:
    """
    Operator class
    """

    _DEFAULT_SUMMAND = Summand  # default class to create summands from


class Basis:
    def __init__(self):
        pass

    def op(self, *vals):
        return Summand(
            (self,),
            (vals,),
        )


class SymbolBasis(Basis):
    """A counting basis counts e.g. the power of a symbol"""


class PauliBasis(Basis):
    """A basis for pauli strings"""


class PauliString(Basis):
    """A pauli string that always refers to a fixed length"""


class MatrixBasis(Basis):
    """
    A basis that generates matrices as operators. Note that
    matrices can be added and scale more directly with the scalars.
    """


